import PDFDocument from 'pdfkit';
import QRCode from 'qrcode';
import path from 'path';
import fs from 'fs';

// Helper to get absolute path to fonts in node_modules
const getFontPath = (fontName) => {
    return path.join(process.cwd(), 'node_modules', 'pdfkit', 'js', 'data', `${fontName}.afm`);
};

export async function generateTicketPDF({ fullName, ticketType, ticketId }) {
    return new Promise(async (resolve, reject) => {
        try {
            const doc = new PDFDocument({ size: 'A6', margin: 0 });
            const chunks = [];

            doc.on('data', chunk => chunks.push(chunk));
            doc.on('end', () => resolve(Buffer.concat(chunks)));

            // --- Background / Header ---
            // Dark Background
            doc.rect(0, 0, doc.page.width, doc.page.height).fill('#1a1a1a');

            // Accent Bar
            doc.rect(0, 0, doc.page.width, 10).fill('#ff8c00');

            // --- Brand Header ---
            doc.fillColor('#ffffff')
                .font(getFontPath('Helvetica-Bold'))
                .fontSize(18)
                .text('ACHIEVERS SUMMIT', 20, 30, { characterSpacing: 2 });

            doc.fillColor('#ff8c00')
                .fontSize(18)
                .text('2026', 220, 30, { italic: true });

            // --- Attendee Info ---
            doc.fillColor('#ffffff')
                .fontSize(10)
                .font(getFontPath('Helvetica'))
                .text('OFFICIAL EVENT TICKET', 20, 65, { characterSpacing: 1 });

            doc.rect(20, 80, doc.page.width - 40, 1).fill('#ffffff');

            doc.fillColor('#ff8c00')
                .fontSize(10)
                .text('ATTENDEE', 20, 100);

            doc.fillColor('#ffffff')
                .fontSize(16)
                .font(getFontPath('Helvetica-Bold'))
                .text(fullName.toUpperCase(), 20, 115);

            doc.fillColor('#ff8c00')
                .fontSize(10)
                .font(getFontPath('Helvetica'))
                .text('CATEGORY', 20, 150);

            doc.fillColor('#ffffff')
                .fontSize(14)
                .font(getFontPath('Helvetica-Bold'))
                .text(ticketType.toUpperCase(), 20, 165);

            doc.fillColor('#ff8c00')
                .fontSize(10)
                .font(getFontPath('Helvetica'))
                .text('TICKET ID', 20, 200);

            doc.fillColor('#ffffff')
                .fontSize(14)
                .font(getFontPath('Helvetica-Bold'))
                .text(ticketId, 20, 215);

            // --- QR Code ---
            const qrData = JSON.stringify({
                id: ticketId,
                name: fullName,
                category: ticketType,
                event: 'Achievers Summit 2026'
            });

            const qrCodeDataURL = await QRCode.toDataURL(qrData, {
                margin: 1,
                color: {
                    dark: '#ffffff',
                    light: '#1a1a1a'
                }
            });

            const qrImageBuffer = Buffer.from(qrCodeDataURL.split(',')[1], 'base64');
            doc.image(qrImageBuffer, 220, 150, { width: 100 });

            // --- Footer / Venue ---
            doc.rect(0, doc.page.height - 60, doc.page.width, 60).fill('#111111');

            doc.fillColor('#666666')
                .fontSize(8)
                .text('VENUE', 20, 370);

            doc.fillColor('#ffffff')
                .fontSize(10)
                .text('Victoria Island, Lagos', 20, 385);

            doc.fillColor('#666666')
                .fontSize(8)
                .text('DATE', 220, 370);

            doc.fillColor('#ffffff')
                .fontSize(10)
                .text('31 March - 01 April', 220, 385);

            doc.end();
        } catch (error) {
            reject(error);
        }
    });
}
